"""Inspect and render PDFs generated by qa-payroll-local; all input is synthetic."""
import json
import sys
from pathlib import Path

root = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(root / '.codex-payroll-local/python'))
import pymupdf as fitz

folder = root / '.codex-payroll-local/qa'
results = []
for name in ['slip-v1.pdf', 'slip-multipage.pdf']:
    document = fitz.open(folder / name)
    texts = []
    for index, page in enumerate(document):
        assert abs(page.rect.width - 595.28) < 2 and abs(page.rect.height - 841.89) < 2, 'A4 required'
        text = page.get_text()
        texts.append(text)
        assert len(text.strip()) > 80, 'Unexpected nearly empty page'
        for block in page.get_text('blocks'):
            assert block[0] >= 0 and block[2] <= page.rect.width + 1, 'Text exceeds page width'
            assert block[1] >= 0 and block[3] <= page.rect.height + 1, 'Text exceeds page height'
        page.get_pixmap(matrix=fitz.Matrix(1.2, 1.2)).save(folder / f'{name[:-4]}-page-{index + 1}.png')
    combined = '\n'.join(texts)
    assert 'Penghasilan bersih' in combined
    if name == 'slip-multipage.pdf':
        assert len(document) >= 2
        for i in range(1, 51):
            assert f'Komponen uji PDF panjang {i}\n' in combined, f'Missing component {i}'
        assert '1.050.000' in combined
    results.append({'file': name, 'pages': len(document), 'a4': True, 'textWithinPage': True})
(folder / 'pdf-results.json').write_text(json.dumps(results, indent=2))
print(json.dumps(results, indent=2))
